def gen(rng):
    def fmt(a):
        return str(len(a)) + "\n" + " ".join(map(str, a))
    tests = [fmt([1, 3, 3, 0, 1]), fmt([0, 1, 2, 3]), fmt([2, 2, 2]), fmt([0]), fmt([1, 1]), fmt([1, 0]),
             fmt([0, 0, 0, 0]), fmt([3, 3, 3, 3])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12, 20, 40):
        for _ in range(2):
            tests.append(fmt([rng.randint(0, n - 1) for _ in range(n)]))
    for n in (5, 10, 30):
        p = list(range(n))
        rng.shuffle(p)
        tests.append(fmt(p))
        q = p[:]
        for _ in range(2):
            q[rng.randrange(n)] = rng.randrange(n)
        tests.append(fmt(q))
    N = 200000
    tests.append(fmt([rng.randint(0, N - 1) for _ in range(N)]))
    tests.append(fmt([N // 2] * N))
    p = list(range(N))
    rng.shuffle(p)
    for _ in range(50):
        p[rng.randrange(N)] = rng.randrange(N)
    tests.append(fmt(p))
    tests.append(fmt([rng.randint(0, 99) for _ in range(N)]))
    return tests

